import{_ as o,a as r,b as i,c as l,d as n,e as s}from"./chunks/zenfc_h743_pinouts_back.Bx_Ftjfo.js";import{_ as d,C as h,o as c,c as p,j as e,a as u,E as m,al as g}from"./chunks/framework.7vp1BMOE.js";const x=JSON.parse('{"title":"ZenFC H743","description":"","frontmatter":{},"headers":[],"relativePath":"uk/flight_controller/zenfc_h743.md","filePath":"uk/flight_controller/zenfc_h743.md"}'),f={name:"uk/flight_controller/zenfc_h743.md"};function b(_,t,S,k,C,P){const a=h("Badge");return c(),p("div",null,[t[0]||(t[0]=e("h1",{id:"zenfc-h743",tabindex:"-1"},[u("ZenFC H743 "),e("a",{class:"header-anchor",href:"#zenfc-h743","aria-label":'Permalink to "ZenFC H743"'},"​")],-1)),m(a,{type:"tip",text:"PX4 main (v2.0)"}),t[1]||(t[1]=g('<div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>PX4 не розробляє цей (або будь-який інший) автопілот. Contact the <a href="https://www.zenithratech.com/contact" target="_blank" rel="noreferrer">manufacturer</a> for hardware support or compliance issues.</p></div><p>The <em>ZenFC H743</em> is a flight controller designed by Zenithra Tech. It is built around the STM32H743 processor with dual Bosch BMI088 IMUs for sensor redundancy, an onboard barometer, and an integrated OSD.</p><p><img src="'+o+'" alt="ZenFC H743 Flight Controller"></p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>This flight controller is <a href="./../flight_controller/autopilot_manufacturer_supported">manufacturer supported</a>.</p></div><h2 id="основні-характеристики" tabindex="-1">Основні характеристики <a class="header-anchor" href="#основні-характеристики" aria-label="Permalink to &quot;Основні характеристики&quot;">​</a></h2><ul><li><strong>MCU:</strong><ul><li>STM32H743VIT6 (32-bit Arm® Cortex®-M7, 480 MHz)</li></ul></li><li><strong>IMU:</strong><ul><li>2x Bosch BMI088 (accel + gyro, independent SPI buses for redundancy)</li></ul></li><li><strong>Barometer:</strong><ul><li>Bosch BMP388</li></ul></li><li><strong>OSD:</strong><ul><li>Onboard AT7456E OSD chip</li></ul></li><li><strong>Interfaces:</strong><ul><li>7x UARTs</li><li>1x CAN</li><li>2x external I2C (I2C1 with GPS connector and dedicated I2C2 connector)</li><li>8x PWM outputs (Dshot supported)</li><li>microSD card slot</li><li>1x USB Type-C</li></ul></li><li><strong>Power:</strong><ul><li>2x ADC (V_BAT &amp; current sense)</li><li>Battery Input range - 2S-6S</li><li>BEC Outputs <ul><li>9V 3A cont.</li><li>5V 3A cont.</li></ul></li></ul></li></ul><h2 id="розміри" tabindex="-1">Розміри <a class="header-anchor" href="#розміри" aria-label="Permalink to &quot;Розміри&quot;">​</a></h2><ul><li><strong>Mounting:</strong> 30.5 mm x 30.5 mm /Φ4mm hole</li><li><strong>Dimensions:</strong> 35mm x 35mm x 8mm</li><li><strong>Weight:</strong> 9g</li></ul><p><img src="'+r+'" alt="ZenFC H743 Dimensions"></p><h2 id="де-купити" tabindex="-1">Де купити <a class="header-anchor" href="#де-купити" aria-label="Permalink to &quot;Де купити&quot;">​</a></h2><p>Order from <a href="https://www.zenithratech.com/solutions/components" target="_blank" rel="noreferrer">Zenithra Tech</a>.</p><h2 id="flight-controller-layout" tabindex="-1">Flight Controller Layout <a class="header-anchor" href="#flight-controller-layout" aria-label="Permalink to &quot;Flight Controller Layout&quot;">​</a></h2><p><img src="'+i+'" alt="ZenFC H743 Layout Front"></p><p><img src="'+l+'" alt="ZenFC H743 Layout Back"></p><h2 id="налаштування-послідовного-порту" tabindex="-1">Налаштування послідовного порту <a class="header-anchor" href="#налаштування-послідовного-порту" aria-label="Permalink to &quot;Налаштування послідовного порту&quot;">​</a></h2><table tabindex="0"><thead><tr><th>UART</th><th>Пристрій</th><th>PX4 Port</th></tr></thead><tbody><tr><td>USART1</td><td>/dev/ttyS0</td><td>GPS1</td></tr><tr><td>USART2</td><td>/dev/ttyS1</td><td>TEL3</td></tr><tr><td>USART3</td><td>/dev/ttyS2</td><td>TEL4</td></tr><tr><td>UART5</td><td>/dev/ttyS3</td><td>TEL1</td></tr><tr><td>USART6</td><td>/dev/ttyS4</td><td>RC</td></tr><tr><td>UART7</td><td>/dev/ttyS5</td><td>TEL2</td></tr><tr><td>UART8</td><td>/dev/ttyS6</td><td>UART6</td></tr></tbody></table><h2 id="connectors-pinout" tabindex="-1">Connectors &amp; Pinout <a class="header-anchor" href="#connectors-pinout" aria-label="Permalink to &quot;Connectors &amp; Pinout&quot;">​</a></h2><p>Board uses JST SH connectors for all interfaces.</p><p><img src="'+n+'" alt="ZenFC H743 Pinouts Front"></p><p><img src="'+s+'" alt="ZenFC H743 Pinouts Back"></p><p><strong>Note</strong> - SBus pin on DJI O3/O4 port is internally connected to RX6 (<code>RCIN</code>).</p><h3 id="pwm-виходи" tabindex="-1">PWM Виходи <a class="header-anchor" href="#pwm-виходи" aria-label="Permalink to &quot;PWM Виходи&quot;">​</a></h3><p>The 8 outputs are in 3 groups:</p><ul><li>Outputs 1-4 in group1</li><li>Outputs 5-6 in group2</li><li>Outputs 7-8 in group3</li></ul><p><strong>Note</strong>:</p><ul><li>All outputs support PWM and <a href="./../peripherals/dshot">DShot</a> protocol. Outputs 1-6 and 8 support &quot;bidirectional DShot&quot; (or &quot;BDShot&quot;) telemetry.</li><li>Outputs 1-4 default to DShot300 (<a href="./../advanced_config/parameter_reference#PWM_MAIN_TIM0">PWM_MAIN_TIM0</a> = <code>-4</code>); outputs 5-6 and 7-8 default to PWM at 400 Hz.</li><li>Each group&#39;s protocol can be changed independently using the corresponding <code>PWM_MAIN_TIMx</code> parameter, including to <a href="./../peripherals/dshot#bidirectional-dshot-telemetry">Bidirectional DShot</a> (BDShot) for ESC telemetry.</li></ul><h3 id="відладочнии-порт" tabindex="-1">Відладочний порт <a class="header-anchor" href="#відладочнии-порт" aria-label="Permalink to &quot;Відладочний порт&quot;">​</a></h3><p>This board does not configure a dedicated UART as a system console. Use the <a href="./../debug/mavlink_shell">MAVLink Shell</a> over USB for console/NSH access using QGroundControl.</p><p><strong>SWD</strong></p><p>The board features a <a href="./../debug/swd_debug"><strong>4-pin SWD Debug</strong></a> interface (3V3 / SWCLK / SWDIO / GND) for hardware debugging.</p><h2 id="радіоуправління" tabindex="-1">Радіоуправління <a class="header-anchor" href="#радіоуправління" aria-label="Permalink to &quot;Радіоуправління&quot;">​</a></h2><p>A <a href="./../getting_started/rc_transmitter_receiver">Radio Control (RC) system</a> is required if you want to manually control your vehicle (PX4 does not require a radio system for autonomous flight modes). See <a href="./../modules/modules_driver_radio_control">Radio Control modules</a> for the list of supported protocols.</p><p>RC input is mapped to <strong>USART6</strong> (<code>/dev/ttyS4</code>, <code>RC</code> port). The port supports both single-wire inverted SBUS and full-duplex protocols with telemetry return (such as CRSF), and the receiver protocol is auto-detected by default (<a href="./../advanced_config/parameter_reference#RC_INPUT_PROTO">RC_INPUT_PROTO</a> = <code>-1</code>).</p><h2 id="конфігурація-px4" tabindex="-1">Конфігурація PX4 <a class="header-anchor" href="#конфігурація-px4" aria-label="Permalink to &quot;Конфігурація PX4&quot;">​</a></h2><p>In addition to the <a href="./../config/">basic configuration</a>, the following parameter is important:</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Налаштування</th></tr></thead><tbody><tr><td><a href="./../advanced_config/parameter_reference#SYS_HAS_MAG">SYS_HAS_MAG</a></td><td>Disabled by default since the board has no internal magnetometer. Enable it if you attach an external mag.</td></tr></tbody></table><h2 id="збірка-прошивки" tabindex="-1">Збірка прошивки <a class="header-anchor" href="#збірка-прошивки" aria-label="Permalink to &quot;Збірка прошивки&quot;">​</a></h2><p>To <a href="./../dev_setup/building_px4">build PX4</a> for this target:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> zenfc_h743_default</span></span></code></pre></div><h2 id="встановлення-прошивки-px4" tabindex="-1">Встановлення прошивки PX4 <a class="header-anchor" href="#встановлення-прошивки-px4" aria-label="Permalink to &quot;Встановлення прошивки PX4&quot;">​</a></h2><p>Прошивку можна встановити будь-якими звичайними способами:</p><ul><li><p>Збудуйте та завантажте джерело:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> zenfc_h743_default</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upload</span></span></code></pre></div></li><li><p><a href="./../config/firmware">Load the firmware</a> using <em>QGroundControl</em>. Ви можете використовувати або готове вбудоване програмне забезпечення, або власне користувацьке програмне забезпечення.</p></li></ul><p>The board uses the standard PX4 bootloader, so it follows the same generic LED indications as most other boards (Red = Bootloader/Error, Blue = Active/Activity, Green = Powered).</p><h2 id="подальша-інформація" tabindex="-1">Подальша інформація <a class="header-anchor" href="#подальша-інформація" aria-label="Permalink to &quot;Подальша інформація&quot;">​</a></h2><ul><li><a href="https://www.zenithratech.com/contact" target="_blank" rel="noreferrer">Zenithra Tech</a></li></ul>',45))])}const v=d(f,[["render",b]]);export{x as __pageData,v as default};
